<template>
  <main class="kb-page">
    <header class="page-heading"><div><p class="eyebrow">我的工作空间</p><h1>知识库<span class="base-count">{{ bases.length }}</span></h1><p class="sub">收藏经验、沉淀方法，让每一份知识都触手可及。</p></div><div class="header-actions"><button type="button" :disabled="!bases.some(base => base.canUpload)" @click="importFor(bases.find(base => base.canUpload)!.id)"><i class="i-lucide-upload" />导入文档</button><button type="button" class="primary-action" @click="modalError = ''; showCreate = true"><i class="i-lucide-plus" />新建知识库</button></div></header>
    <div class="list-toolbar"><span>全部知识库</span><label><i class="i-lucide-search" /><input v-model="baseSearch" placeholder="搜索知识库" aria-label="搜索知识库" /></label></div>
    <p v-if="error" class="error" role="alert">{{ error }} <button type="button" @click="load">重试</button></p><p v-if="importNotice" class="import-notice" role="status">{{ importNotice }}</p>
    <section v-if="loading" class="state">正在加载知识库…</section>
    <section v-else-if="!bases.length" class="state"><span class="empty-library"><i class="i-lucide-library" /></span><strong>知识，从这里开始</strong><p>新建知识库，把文档与团队经验整理在一起。</p><button type="button" @click="showCreate = true">新建知识库</button></section>
    <section v-else-if="!filteredBases.length" class="state">没有找到匹配的知识库</section>
    <ul v-else class="base-grid"><li v-for="base in filteredBases" :key="base.id"><div class="card-top"><span class="library-icon"><i class="i-lucide-library" /></span><span class="role-badge">{{ base.canEditSettings ? '创建者 / 管理' : base.canManage ? '管理员' : base.canUpload ? '可编辑' : '只读' }}</span></div><a class="card-title" :href="`#/knowledge-bases/${base.id}`">{{ base.name }}</a><p class="card-description">{{ base.description || '还没有简介，为这里的知识写一句介绍吧。' }}</p><div class="card-actions"><button type="button" @click="open(base.id)">打开知识库<i class="i-lucide-arrow-right" /></button><span /><button v-if="base.canUpload" type="button" :aria-label="`导入到 ${base.name}`" @click="importFor(base.id)"><i class="i-lucide-upload" /></button><RouterLink v-if="base.canManage" :to="`/knowledge-bases/${base.id}/settings`" class="settings-link" :aria-label="`设置 ${base.name}`"><i class="i-lucide-settings-2" />设置</RouterLink></div></li></ul>

    <div v-if="showCreate" class="modal" role="dialog" aria-label="新建知识库"><form class="modal-card" @submit.prevent="create"><header><strong>新建知识库</strong><button type="button" @click="showCreate = false">×</button></header><label>名称<input v-model.trim="createForm.name" required maxlength="200" /></label><label>描述<textarea v-model.trim="createForm.description" maxlength="2000"></textarea></label><p v-if="modalError" class="error" role="alert">{{ modalError }}</p><footer><button type="button" @click="showCreate = false">取消</button><button type="submit" :disabled="saving || !createForm.name">{{ saving ? '创建中…' : '创建' }}</button></footer></form></div>
    <div v-if="showImport" class="modal" role="dialog" aria-label="导入文档"><form class="modal-card import-card" @submit.prevent="upload"><header><strong>导入为 Wiki 文档</strong><button type="button" @click="showImport = false" :disabled="saving">×</button></header><label>所在知识库<select v-model="importForm.kbId" required :disabled="saving"><option v-for="base in bases.filter(base => base.canUpload)" :key="base.id" :value="base.id">{{ base.name }}</option></select></label><label>可见范围<select :disabled="saving" v-model="importForm.audience" @change="scheduleCandidates"><option value="PRIVATE">仅自己</option><option value="SELECTED_MEMBERS">指定知识库成员</option><option value="KB_MEMBERS">知识库成员</option></select></label><section v-if="importForm.audience === 'SELECTED_MEMBERS'" class="audience-picker"><aside><strong>可选知识库</strong><button v-for="base in bases" :key="base.id" type="button" :class="{ selected: sourceKbId === base.id }" @click="sourceKbId = base.id; scheduleCandidates()">{{ base.name }}</button></aside><div class="audience-members"><strong>选择人员</strong><input v-model.trim="memberQuery" placeholder="按用户名搜索" @input="scheduleCandidates" /><div v-if="candidateLoading" class="hint">搜索中…</div><button v-for="candidate in candidates" :key="`${sourceKbId}-${candidate.id}`" type="button" class="candidate" :class="{ checked: isSelected(candidate.id) }" @click="toggleCandidate(candidate)">{{ isSelected(candidate.id) ? '✓ ' : '' }}{{ candidate.username }}<span>{{ candidate.displayName || '' }}</span></button><p v-if="selectedMembers.length" class="selected-list">已选：<span v-for="member in selectedMembers" :key="`${member.sourceKbId}-${member.userId}`" class="chip">{{ member.username }} <button type="button" @click="removeMember(member)">×</button></span></p></div></section><label>文件<input :disabled="saving" type="file" accept=".md,.markdown,.docx" required @change="onFile" /></label><p class="hint">支持 Markdown、DOCX，单个文件不超过 20 MB。保留文字内容，图片不参与解析。</p><p v-if="failedJobId" class="hint">导入任务 #{{ failedJobId }}</p><p v-if="modalError" class="error" role="alert">{{ modalError }}</p><footer><button type="button" @click="showImport = false" :disabled="saving">取消</button><button v-if="failedJobId" type="button" @click="retryImport" :disabled="saving">重试解析</button><button type="submit" :disabled="saving || !importForm.file || !!failedJobId">{{ saving ? uploadStage : '上传并解析' }}</button></footer></form></div>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { RouterLink, useRoute, useRouter } from 'vue-router';
import { useWikiStore } from '../wiki/store';
import { api, errorMessage } from '../wiki/api';


interface Base { id: number; uuid: string; name: string; description?: string; canManage?: boolean; canUpload?: boolean; canEditSettings?: boolean; }
interface Candidate { id: number; username: string; displayName?: string; }
interface SelectedMember extends Candidate { sourceKbId: number; userId: number; }
const route = useRoute(); const router = useRouter(); const wiki = useWikiStore();
const baseSearch = ref(''); const bases = ref<Base[]>([]);
const filteredBases = computed(() => bases.value.filter(base => (base.name + (base.description || '')).toLowerCase().includes(baseSearch.value.toLowerCase()))); const loading = ref(false); const saving = ref(false); const error = ref(''); const importNotice = ref(''); const modalError = ref(''); const showCreate = ref(false); const showImport = ref(false); const failedJobId = ref<number | null>(null);
const createForm = ref({ name: '', description: '' }); const importForm = ref<{ kbId: number | ''; audience: string; file: File | null }>({ kbId: '', audience: 'PRIVATE', file: null });
const sourceKbId = ref<number | ''>(''); const memberQuery = ref(''); const candidates = ref<Candidate[]>([]); const selectedMembers = ref<SelectedMember[]>([]); const candidateLoading = ref(false);
let candidateTimer: ReturnType<typeof setTimeout> | undefined;
async function load() { loading.value = true; error.value = ''; try { bases.value = await api.json<Base[]>('/knowledge-bases'); wiki.knowledgeBases = bases.value; if (!importForm.value.kbId) importForm.value.kbId = bases.value.find(base => base.canUpload)?.id ?? '';  } catch { error.value = '知识库加载失败，请重试'; } finally { loading.value = false; } }
async function create() { saving.value = true; modalError.value = ''; try { const base = await api.post<Base>('/knowledge-bases', createForm.value); showCreate.value = false; createForm.value = { name: '', description: '' }; await load(); if (base?.id) open(base.id); } catch { modalError.value = '知识库创建失败，请重试'; } finally { saving.value = false; } }
function importFor(id: number) { uploadKey = ''; importForm.value.file = null; importForm.value.kbId = id; showImport.value = true; modalError.value = ''; failedJobId.value = null; sourceKbId.value = id; memberQuery.value = ''; candidates.value = []; selectedMembers.value = []; }
function onFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0] ?? null; modalError.value = ''; failedJobId.value = null; uploadKey = ''; importForm.value.file = file; if (file && (file.size > 20 * 1024 * 1024 || file.size === 0 || !/\.(md|markdown|docx)$/i.test(file.name))) { modalError.value = '请选择非空的 Markdown 或 DOCX 文件，大小不超过 20 MB'; importForm.value.file = null; } }
function scheduleCandidates() { if (candidateTimer) clearTimeout(candidateTimer); candidateTimer = setTimeout(() => { void searchCandidates(); }, 200); }
async function searchCandidates() { if (!importForm.value.kbId || !sourceKbId.value || importForm.value.audience !== 'SELECTED_MEMBERS') return; candidateLoading.value = true; try { candidates.value = await api.json<Candidate[]>(`/knowledge-bases/${importForm.value.kbId}/audience-candidates?sourceKbId=${sourceKbId.value}&q=${encodeURIComponent(memberQuery.value)}&limit=20`); } catch { candidates.value = []; } finally { candidateLoading.value = false; } }
function isSelected(id: number) { return selectedMembers.value.some((member) => member.sourceKbId === sourceKbId.value && member.userId === id); }
function toggleCandidate(candidate: Candidate) { if (!sourceKbId.value) return; if (isSelected(candidate.id)) selectedMembers.value = selectedMembers.value.filter((member) => !(member.sourceKbId === sourceKbId.value && member.userId === candidate.id)); else selectedMembers.value.push({ ...candidate, sourceKbId: sourceKbId.value, userId: candidate.id }); }
function removeMember(member: SelectedMember) { selectedMembers.value = selectedMembers.value.filter((item) => item !== member); }
type ImportResult = { jobId: number; state: string; pageId?: number; warnings?: string[]; error?: string };
let uploadKey = ''; const uploadStage = ref('');
async function handleImport(result: ImportResult, kb: number) {
  const started = Date.now();
  while (!['SUCCEEDED', 'FAILED'].includes(result.state)) {
    uploadStage.value = '文档解析中…';
    if (Date.now() - started > 120000) { failedJobId.value = result.jobId; throw { message: '文档仍在处理中，请稍后查看结果' }; }
    await new Promise(resolve => setTimeout(resolve, 1000));
    result = await api.json<ImportResult>(`/knowledge-bases/${kb}/imports/${result.jobId}`);
  }
  if (result.state === 'FAILED') { failedJobId.value = result.jobId; modalError.value = result.error || '导入失败，请重试'; return; }
  if (result.warnings?.length) importNotice.value = result.warnings.join('；');
  else importNotice.value = '文档已导入并发布';
  showImport.value = false;
  if (result.pageId) await router.push({ name: 'workspace', params: { kbId: kb, pageId: result.pageId }, query: result.warnings?.length ? { imported: result.warnings.join('；') } : {} });
}
async function upload() {
  if (!importForm.value.file || !importForm.value.kbId || saving.value) return;
  if (importForm.value.audience === 'SELECTED_MEMBERS' && !selectedMembers.value.length) { modalError.value = '指定成员模式至少选择一名成员'; return; }
  saving.value = true; modalError.value = ''; importNotice.value = ''; uploadStage.value = '上传并处理文档…';
  try {
    const kb = Number(importForm.value.kbId);
    const form = new FormData(); form.set('file', importForm.value.file); form.set('audienceMode', importForm.value.audience);
    if (selectedMembers.value.length) form.set('audienceMembers', selectedMembers.value.map(member => `${member.sourceKbId}:${member.userId}`).join(','));
    uploadKey ||= crypto.randomUUID();
    await handleImport(await api.upload<ImportResult>(`/knowledge-bases/${kb}/imports`, form, undefined, uploadKey), kb);
  } catch(e) { modalError.value = errorMessage(e, '上传未完成，请检查网络后重试'); } finally { saving.value = false; uploadStage.value = ''; }
}
async function retryImport() {
  if (!failedJobId.value || !importForm.value.kbId || saving.value) return;
  saving.value = true; modalError.value = ''; uploadStage.value = '正在重试…';
  try { await handleImport(await api.post<ImportResult>(`/knowledge-bases/${importForm.value.kbId}/imports/${failedJobId.value}/retry`), Number(importForm.value.kbId)); }
  catch(e) { modalError.value = errorMessage(e, '重试失败，请稍后再试'); } finally { saving.value = false; uploadStage.value = ''; }
}
function open(id: number) { window.location.hash = `#/knowledge-bases/${id}`; }
onMounted(async () => { await load(); const target = Number(route.query.import); if (target && bases.value.some(base => base.id === target && base.canUpload)) importFor(target); });
</script>

<style scoped>
.kb-page { min-height:100vh; max-width:1040px; margin:0 auto; padding:56px 28px; color:#26352e; } header { display:flex; justify-content:space-between; align-items:flex-start; gap:20px; } .eyebrow { margin:0 0 8px; color:#1b9d61; font-size:12px; font-weight:700; text-transform:uppercase; } h1 { margin:0; font-size:32px; } .sub,.hint { color:#77847c; } .header-actions,.card-actions { display:flex; gap:8px; align-items:center; } button { padding:9px 13px; border:1px solid #cedbd3; border-radius:7px; background:#fff; cursor:pointer; } .header-actions button:last-child,.card-actions button:first-child,footer button:last-child { background:#1b9d61; border-color:#1b9d61; color:#fff; } button:disabled { opacity:.5; cursor:default; } .base-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(270px,1fr)); gap:12px; margin:34px 0; padding:0; list-style:none; } .base-grid li { display:flex; flex-direction:column; justify-content:space-between; min-height:130px; padding:18px; border:1px solid #e1e9e4; border-radius:11px; background:#fff; } .base-grid p { color:#77847c; font-size:13px; } .state { margin-top:38px; padding:44px; border:1px dashed #cbd9d1; border-radius:14px; color:#718078; text-align:center; } .state p { margin-bottom:20px; } .error { color:#b24a4a; } .import-notice { margin:20px 0 0; padding:10px 13px; border-radius:8px; background:#f0faf4; color:#187b4a; } .modal { position:fixed; inset:0; z-index:50; display:grid; place-items:center; padding:20px; background:#1c282255; } .modal-card { width:min(520px,100%); display:grid; gap:14px; padding:20px; border-radius:12px; background:#fff; box-shadow:0 20px 60px #17261d33; } .modal-card header { display:flex; align-items:center; justify-content:space-between; } .modal-card header button { border:0; background:none; font-size:22px; padding:0; } label { display:grid; gap:6px; color:#46564d; font-size:13px; } input,textarea,select { box-sizing:border-box; width:100%; padding:9px; border:1px solid #dfe7e2; border-radius:7px; font:inherit; } textarea { min-height:80px; resize:vertical; } footer { display:flex; justify-content:flex-end; gap:8px; }
.import-card { width:min(720px,100%); max-height:90vh; overflow:auto; }
.audience-picker { display:grid; grid-template-columns:180px minmax(0,1fr); min-height:190px; border:1px solid #e1e9e4; border-radius:8px; overflow:hidden; }
.audience-picker aside { display:grid; align-content:start; gap:4px; padding:10px; background:#f7faf8; border-right:1px solid #e1e9e4; }
.audience-picker aside button { padding:8px; border:0; text-align:left; background:transparent; }
.audience-picker aside button.selected { background:#e1f5e9; color:#167c4b; }
.audience-members { display:grid; align-content:start; gap:7px; padding:10px; }
.candidate { display:flex; gap:8px; align-items:center; padding:7px 8px; border:0; background:#fff; text-align:left; }
.candidate span { margin-left:auto; color:#8a968f; font-size:12px; }
.candidate.checked { background:#eaf8f0; color:#167c4b; }
.selected-list { margin:3px 0 0; font-size:12px; color:#65736a; }
.chip { display:inline-flex; gap:3px; align-items:center; margin:3px 3px 0 0; padding:3px 7px; border-radius:99px; background:#edf7f1; }
.chip button { padding:0; border:0; background:none; color:#4f7561; }
@media (max-width:640px) { header { display:block; } .header-actions { margin-top:16px; } }
</style>

